import{b as i,O as a,g as t,j as n}from"./chunks/framework.DcaUmd3X.js";const l="/assets/image.cNxcb9rv.webp",e="/assets/image-1.BIKtyN-u.webp",F=JSON.parse('{"title":"工作区与暂存区","description":"","frontmatter":{},"headers":[],"relativePath":"git/basics/staging/index.md","filePath":"Git操作手册/2.基础操作/03.工作区与暂存区.md","lastUpdated":1783947942000}'),p={name:"git/basics/staging/index.md"};function h(k,s,d,o,r,g){return a(),t("div",null,[...s[0]||(s[0]=[n('<h1 id="工作区与暂存区" tabindex="-1">工作区与暂存区 <a class="header-anchor" href="#工作区与暂存区" aria-label="Permalink to &quot;工作区与暂存区&quot;">​</a></h1><blockquote><p>理解 Git 的三层流转，不再&quot;add 完不知道发生了什么&quot;</p></blockquote><h2 id="git-的三个区域" tabindex="-1">Git 的三个区域 <a class="header-anchor" href="#git-的三个区域" aria-label="Permalink to &quot;Git 的三个区域&quot;">​</a></h2><p>前面几章你一直在用 <code>git add</code> 和 <code>git commit</code>，但 Git 为什么要分两步？不能像 Ctrl+S 一样一步保存吗？</p><p>因为 Git 把&quot;保存&quot;拆成了三个区域，给你精确控制权：</p><p><img src="'+l+`" alt="alt text"></p><p><strong>打个比方：</strong></p><ul><li><strong>工作区</strong> = 你的办公桌，文件散在桌上，随时改</li><li><strong>暂存区</strong> = 快递打包盒，从桌上挑出要寄的东西放进去</li><li><strong>版本库</strong> = 快递已发出，打包盒封好、贴上标签、存入仓库，永久归档</li></ul><h2 id="为什么需要暂存区" tabindex="-1">为什么需要暂存区 <a class="header-anchor" href="#为什么需要暂存区" aria-label="Permalink to &quot;为什么需要暂存区&quot;">​</a></h2><p>分两步给了你&quot;选择性提交&quot;的自由。比如说你同时改了两个文件：</p><ul><li><code>app.js</code> — 修了一个紧急 bug</li><li><code>style.css</code> — 在做新功能的样式，还没写完</li></ul><p>你不希望把没写完的样式跟着 bug 修复一起提交。有了暂存区，你可以：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.js</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 只把 bug 修复加入暂存区</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修复登录按钮失效的 bug&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 提交只包含 app.js</span></span></code></pre></div><p><code>style.css</code> 的改动还在工作区，不影响这次提交。这就是暂存区的价值——<strong>一次提交不一定是所有修改，而是你挑选的一组修改</strong>。</p><h2 id="文件在三个区域之间流动" tabindex="-1">文件在三个区域之间流动 <a class="header-anchor" href="#文件在三个区域之间流动" aria-label="Permalink to &quot;文件在三个区域之间流动&quot;">​</a></h2><p>用 <code>git status</code> 可以清楚看到文件当前的状态：</p><p><img src="`+e+`" alt="alt text"></p><p>来实际操作一遍，感受三层流转。你改了一个文件 <code>app.js</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第一步：改完文件，看状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 红色：modified:   app.js    ← 在工作区，还没进暂存区</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第二步：加入暂存区</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 绿色：modified:   app.js    ← 进了暂存区，等着提交</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第三步：提交到版本库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;更新 app.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nothing to commit, working tree clean   ← 全部归档，干干净净</span></span></code></pre></div><h2 id="暂存区的内容可以被覆盖" tabindex="-1">暂存区的内容可以被覆盖 <a class="header-anchor" href="#暂存区的内容可以被覆盖" aria-label="Permalink to &quot;暂存区的内容可以被覆盖&quot;">​</a></h2><p>同一个文件多次 <code>git add</code>，暂存区只保留最后一次 add 的内容：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v1&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 暂存区存的是 &quot;v1&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;v2&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 暂存区更新为 &quot;v2&quot;，v1 被覆盖</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;提交的是 v2&quot;</span></span></code></pre></div><blockquote><p>💡 这就是 <code>git add</code> 的真正含义：不是&quot;保存文件&quot;，而是&quot;把文件当前状态加入暂存区&quot;。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Git 的三层模型是理解后面所有操作的基础：</p><ol><li><strong>工作区</strong> — 你写代码的地方，文件改了就生效</li><li><strong>暂存区</strong> — 你挑选哪些文件参与本次提交，<code>git add</code> 就是往这里放</li><li><strong>版本库</strong> — <code>git commit</code> 把暂存区内容打包存入永久历史</li></ol><p>不需要一口气全选——挑 bug 修复提交、新功能留着继续写，这是暂存区给你的灵活度。</p><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>同时修改两个文件，只 <code>git add</code> 其中一个，用 <code>git status</code> 观察两个文件分别在哪里</li><li>对同一个文件改三次、add 三次，确认最终提交的是最后一次的内容</li><li>用你自己的话解释：为什么 Git 要分工作区和暂存区？分一步提交不行吗？</li></ol>`,29)])])}const u=i(p,[["render",h]]);export{F as __pageData,u as default};
